param([Parameter(Mandatory=$true)][ValidateSet('smoke','coarse','half')][string]$Window)
# One pure BI4 decode, never a solver, rebuild, seed preparation or automatic next stage.
$ErrorActionPreference='Stop';$Window=$Window.ToLowerInvariant();$smoke=$Window -ceq 'smoke';$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$tag='upl_gpu_column_actual_'+$Window+'_r2'
$solverDir=Join-Path $tests ('outputs\'+$tag);$out=Join-Path $tests ('outputs\'+$tag+'_native');$record=Join-Path $logs ($tag+'.native.json');$callPath=Join-Path $logs ($tag+'_native.call.json');$log=Join-Path $logs ($tag+'_native.log')
$samples=if($smoke){3}else{769};$steps=if($smoke){2}elseif($Window -ceq 'coarse'){10000}else{20000};$dt=if($Window -ceq 'half'){1.25e-6}else{2.5e-6};$dtText=if($Window -ceq 'half'){'0.00000125'}else{'0.0000025'}
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$yes,[string]$why){if(!$yes){throw $why}}
function V($rows){foreach($r in $rows){Need ([bool]$r.path) 'Missing bound Entry';$a=E $r.path;Need ($a.bytes -eq $r.bytes -and $a.sha256 -ieq $r.sha256) ('Changed artifact: '+$r.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function N($v){Need ($null -ne $v -and [string]$v -ne '') 'Missing number';$n=if($v -is [ValueType]){[double]$v}else{[double]::Parse([string]$v,[Globalization.CultureInfo]::InvariantCulture)};Need (![double]::IsNaN($n) -and ![double]::IsInfinity($n)) 'Nonfinite number';return $n}
function Owned($e){V @($e);$v=J $e.path;Need ($v.owned_call_exited -and $v.typed_LASTEXITCODE_captured_immediately -and $v.exit_code -is [int] -and $v.exit_code -eq 0) 'Owned immediate typed native exit0 required';V @($v.program,$v.log)}
Fresh @($out,$record,$callPath,$log)
$runPath=Join-Path $logs ($tag+'.run.json');$r=J $runPath;Need ($r.passed) 'Own actual Run rejected; no native process may start';$actual=J $r.actual_complete.path;$rh=J $r.helper.path
Need ($r.passed -and $r.window -ceq $Window -and $r.planned_steps -eq $steps -and $r.planned_samples -eq $samples -and (N $r.planned_dt_s) -eq $dt -and $r.source_inputs_objects_runtime_canonical_unchanged -and $r.all_raw_outputs_hash_bound -and $r.physical_acceptance -eq $false -and $actual.passed -and $actual.window -ceq $Window -and $actual.completed_steps -eq $steps -and $actual.saved_parts -eq $samples -and $actual.physical_acceptance -eq $false) 'Own completed safe actual Run required'
Owned $r.call;$solverCall=J $r.call.path;Need ($solverCall.actual_solver_call -and $solverCall.target_program.sha256 -ieq $rh.program.sha256) 'Actual target ownership differs'
if($smoke){Need ($r.configuration -ceq 'Debug' -and $r.memcheck_executed -and $r.memcheck_zero_errors_and_leaks) 'Actual Debug smoke memcheck0/0 required'}else{Need ($r.configuration -ceq 'Release') 'Actual full window must be Release'}
$hp=Join-Path $logs 'upl_gpu_column_native_Release_r1.helper.json';$h=J $hp;$b=J $h.source_build.path;$s=J $h.source_freeze.path;$rs=J $r.source_freeze.path
Need ($h.passed -and $h.status -ceq 'current_column_GPU_helper_linked_not_run' -and $h.kind -ceq 'native' -and $h.configuration -ceq 'Release' -and $h.exact_link_closure_verified -and $h.link_object_count -eq 111 -and @($h.objects).Count -eq 110 -and @($h.runtime).Count -eq 4 -and $h.source_and_protected_artifacts_unchanged -and !$h.program_run -and !$h.solver_started) 'Passed already-built current Release pure decoder required'
Need ($b.passed -and $b.objects_exclude_main -and @($s.source).Count -eq 265 -and @($s.current_source_snapshot).Count -eq 265 -and @($s.canonical_programs_before).Count -eq 7 -and @($s.runtime_before).Count -eq 4 -and @($rs.source).Count -eq 265) 'Current265source/110objects/7canonical/4runtime closure required'
Owned $h.compile_call;Owned $h.link_call
$sourceMap=@{};foreach($p in $s.source){Need (!$sourceMap.ContainsKey($p.path)) 'Duplicate current source identity';$sourceMap[$p.path]=$p};$seen=@{}
foreach($p in $rs.source){Need ($sourceMap.ContainsKey($p.path) -and !$seen.ContainsKey($p.path)) 'Solver/reader source set differs';$v=$sourceMap[$p.path];Need ($v.bytes -eq $p.bytes -and $v.sha256 -ieq $p.sha256) 'Solver/reader current source bytes differ';$seen[$p.path]=$true}
$livePath=Join-Path $solverDir 'live_final.csv';$liveBound=@($r.files|Where-Object {$_.path -ieq $livePath});Need ($liveBound.Count -eq 1) 'Actual live-final must be sealed once'
$inputs=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_gpu_column_native_run_r1.json')),(E $runPath),$r.call,$r.actual_complete,$r.helper,$r.source_build,$r.source_freeze,(E $hp),$h.source_build,$h.source_freeze,$h.program,$h.compile_call,$h.link_call,$liveBound[0])
function Verify{
  V $inputs;V $r.inputs;V $r.files;V @($solverCall.program,$solverCall.target_program,$solverCall.log);V $h.inputs;V $h.author_files;V $h.objects;V $h.tools;V $h.libraries;V @($h.helper_object)
  V $s.source;V $s.canonical_programs_before;V $s.runtime_before;V @($s.documentation_snapshot.original,$s.documentation_snapshot.snapshot);foreach($p in $s.current_source_snapshot){V @($p.original,$p.snapshot)};foreach($p in $h.runtime){V @($p.original,$p.copy)};foreach($p in $b.runtime){V @($p.original,$p.copy)}
}
Verify
$argv=@('--read',(Join-Path $solverDir 'data'),[string]$samples,$dtText,$out);[IO.File]::WriteAllBytes($log,[byte[]]@());$start=[DateTime]::UtcNow.ToString('o');$code=$null;$launchFailure=$null;$saved=$ErrorActionPreference
Push-Location (Split-Path -Parent $h.program.path)
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $h.program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$launchFailure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$h.program;arguments=$argv;working_directory=(Split-Path -Parent $h.program.path);started_utc=$start;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$launchFailure;log=(E $log);pure_reader_only=$true;actual_solver_call=$false;physical_acceptance=$false})
$failure=$launchFailure;$completion=$null;$done=$null;$files=@();$unchanged=$false;$last=$null;$liveExact=$false
try{
  Need ($code -is [int] -and $code -eq 0 -and !$launchFailure) 'Pure reader rejected; do not rerun the solver'
  $completion=E (Join-Path $out 'completion.json');$done=J $completion.path;$expectedWindow=if($smoke){'smoke'}else{'window25'};$grid=if($Window -ceq 'half'){'h'}else{'c'}
  Need ($done.passed -and $done.stage -ceq 'upl_gpu_column_native_r1' -and $done.window -ceq $expectedWindow -and $done.grid -ceq $grid -and $done.backend -ceq 'GPU_private' -and $done.model -ceq 'constant' -and $done.native_count -eq 1000 -and $done.fixed_count -eq 40 -and $done.total_native_count -eq 1040 -and $done.samples -eq $samples -and $done.physical_columns -eq 26 -and $done.physical_schema -ceq 'case02_private26_col21_ExcessPorePress_NOT_wave26' -and $done.original_typed_arrays -eq 15 -and $done.native_J_arrays -eq 3 -and $done.fixed_n_is_GPU_mirror_sample_not_CPU_zero_marker -and $done.fixed_J_n_saturated_domain_checked -and $done.public_model_metadata_absent_global_and_part -and !$done.native_PosDiv_present -and !$done.native_V_rho_k_present -and $done.V_rho_k_derived_not_native -and !$done.physical_acceptance) 'Private18/native1040/soil26/fixedGPUmirror schema rejected'
  Need ((N $done.dt_s) -eq $dt -and (N $done.actual_end_s) -eq (N $actual.actual_end_s) -and $done.planned_completed_steps -eq $steps -and $done.declared_saved_completed_steps_exact -and $done.actual_time_step_locked_dt_exact -and $done.noninitial_signed_dterror_intervals -eq ($samples-1) -and $done.initial_empty_dterror_intervals -le 1 -and $done.initial_dterror_excluded_from_noninitial_summary -and (N $done.max_noninitial_signed_dterror_s) -le 1e-14 -and $done.soil_ledger_checks -eq (1000*$samples) -and $done.fixed_mirror_sample_checks -eq (40*$samples) -and (N $done.max_ledger_relative_error) -le 5e-13 -and $done.no_exclusions -and $done.initial_rest_and_decimal_lattice_verified -and $done.double_stress_and_float_display_verified -and $done.all_exported_physical_fields_finite) 'Native saved-clock/ledger/elastic/finite guard rejected'
  $postFrames=if($smoke){0}else{359};$drainThreshold=if($Window -ceq 'half'){8000}else{4000}
  Need ($done.post_open_frames -eq $postFrames -and $done.post_open_completed_step_threshold -eq $drainThreshold -and $done.post_open_drained_particle_checks -eq (10*$postFrames) -and $done.max_activeDrainCount -eq $(if($smoke){0}else{10}) -and $done.pre_open_event_pressure_not_forced_zero -and $done.density_and_J_not_frozen_on_drained_receivers) 'Actual post-open native drainage10x359 coverage rejected'
  # Only the small history is traversed; large native ledger/fixed CSV formula checks stay in CPP.
  $history=@(Import-Csv -LiteralPath (Join-Path $out 'history.csv'));Need ($history.Count -eq $samples) 'History coverage differs'
  foreach($row in $history){$completed=N $row.completed_step;$active=N $row.activeDrainCount;Need ($active -eq $(if($completed -gt $drainThreshold){10}else{0})) 'Each saved post-open frame must expose10 drained receivers'}
  foreach($spec in @(@('original15.bin',(12+$samples*(8+166400)),1040,15),@('physical.bin',(12+$samples*(8+1000*26*8)),1000,26),@('clock.bin',(8+$samples*28),$samples,28))){$path=Join-Path $out $spec[0];Need ((Get-Item -LiteralPath $path).Length -eq $spec[1]) 'Native binary byte count differs';$stream=[IO.File]::OpenRead($path);try{$header=New-Object byte[] 12;$read=$stream.Read($header,0,12);Need ($read -eq 12 -and [BitConverter]::ToUInt32($header,0) -eq $spec[2] -and [BitConverter]::ToUInt32($header,4) -eq $spec[3]) 'Native binary header differs';if($spec[0] -cne 'clock.bin'){Need ([BitConverter]::ToUInt32($header,8) -eq $samples) 'Native binary sample header differs'}}finally{$stream.Dispose()}}
  $last=E (Join-Path $out 'last_poro.csv');$live=E $livePath;$liveExact=($last.bytes -eq $live.bytes -and $last.sha256 -ceq $live.sha256);Need ($liveExact -and @(Import-Csv -LiteralPath $last.path).Count -eq 1000) 'Final native soil J/n/theta must byte-match actual GPU live-final'
}catch{$failure=$_.Exception.Message}
try{Verify;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
if(Test-Path -LiteralPath $out){$files=@(Get-ChildItem -LiteralPath $out -File|Sort-Object FullName|ForEach-Object {E $_.FullName})}
$passed=(!$failure -and $unchanged -and $code -is [int] -and $code -eq 0 -and $null -ne $done -and $liveExact)
Save $record ([ordered]@{stage='upl_gpu_column_native_run_r1';passed=[bool]$passed;window=$Window;inputs=$inputs;files=$files;source_run=(E $runPath);source_build=$r.source_build;source_freeze=$r.source_freeze;reader_build=(E $hp);reader_call=(E $callPath);completion=$completion;paths=@{native_dir=$out;solver_dir=$solverDir};live_final=@{live=$liveBound[0];native=$last;byte_exact=$liveExact;soil_rows=1000};source_input_raw_program_runtime_canonical_unchanged=$unchanged;owned_reader_exit0=($code -is [int] -and $code -eq 0);saved_native_integrity_only=$true;post_open_nonempty_native_guard_checked=($passed -and !$smoke);CPU_cross_or_half_compared=$false;force_stage_load_or_flux_verified=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "Native decode rejected; preserve $record and outputs, repair analysis only, never rerun solver"}
Write-Output "One native decode sealed, no CPUcross or half started: $record"

